class Solution {
public:
    long long findMaximumScore(std::vector<int>& nums) {
        long long score = 0;
        long long running_max = 0;
        int n = nums.size();
        for (int i = 0; i < n - 1; ++i) {
            running_max = std::max(running_max, (long long)nums[i]);
            score += running_max;
        }
        return score;
    }
};

class Solution {
    public long findMaximumScore(java.util.List<Integer> nums) {
        long score = 0;
        long runningMax = 0;
        int n = nums.size();
        for (int i = 0; i < n - 1; i++) {
            runningMax = Math.max(runningMax, (long) nums.get(i));
            score += runningMax;
        }
        return score;
    }
}

var findMaximumScore = function(nums) {
    let score = 0;
    let runningMax = 0;
    const n = nums.length;
    for (let i = 0; i < n - 1; i++) {
        runningMax = Math.max(runningMax, nums[i]);
        score += runningMax;
    }
    return score;
};
